:root {
  color-scheme: light;
  --ink: #20263d;
  --muted: #727990;
  --paper: #fffdf8;
  --violet: #6555d9;
  --violet-dark: #4d3fc0;
  --mint: #baf2d7;
  --line: #e8e5ef;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body {
  min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center;
  background-color: #e9e7fb;
  background-image: radial-gradient(#bcb8ec 1.5px, transparent 1.5px);
  background-size: 22px 22px; color: var(--ink);
  font: 16px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
}
.card { width: min(100%, 480px); padding: 34px 38px 26px; border: 2px solid var(--ink); border-radius: 18px; background: var(--paper); box-shadow: 8px 8px 0 var(--ink); }
.pixel-mark { width: 42px; height: 42px; display: grid; place-items: center; position: relative; border: 2px solid var(--ink); border-radius: 12px; background: var(--mint); font-size: 23px; font-weight: 850; }
.pixel-mark span { position: absolute; right: -9px; top: -11px; color: var(--violet); font-size: 17px; }
.eyebrow { margin: 22px 0 5px; color: var(--violet-dark); font-size: 13px; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(25px, 7vw, 32px); line-height: 1.2; letter-spacing: -.04em; }
.intro { margin: 8px 0 24px; color: var(--muted); }
.progress-wrap { margin-bottom: 28px; }
.progress-label { display: flex; justify-content: space-between; gap: 12px; margin-bottom: 9px; color: var(--muted); font-size: 14px; font-weight: 650; }
.progress-label span:last-child { color: var(--ink); }
.progress-track { height: 10px; overflow: hidden; border: 1px solid var(--ink); border-radius: 99px; background: #efedf5; }
.progress-track span { display: block; width: 33.333%; height: 100%; border-radius: inherit; background: var(--violet); transition: width .2s ease; }
.step h2 { margin: 0 0 17px; font-size: 20px; letter-spacing: -.02em; }
.step > label { display: block; margin: 15px 0 6px; font-size: 14px; font-weight: 700; }
input[type="text"], input[type="email"] { width: 100%; min-height: 50px; padding: 11px 13px; border: 1.5px solid #cbc8d8; border-radius: 9px; background: white; color: var(--ink); font: inherit; }
input::placeholder { color: #989bad; }
input:focus-visible, button:focus-visible, .plan:focus-within { outline: 3px solid #aa9fff; outline-offset: 3px; }
.step-hint { margin: -11px 0 17px; color: var(--muted); }
.plans { display: grid; gap: 10px; margin: 0; padding: 0; border: 0; }
.plan { min-height: 70px; display: flex; align-items: center; gap: 12px; padding: 11px 14px; border: 1.5px solid var(--line); border-radius: 10px; cursor: pointer; transition: border-color .15s, background .15s, transform .1s; }
.plan:hover { border-color: var(--violet); background: #f8f6ff; }
.plan:active { transform: scale(.99); }
.plan:has(input:checked) { border-color: var(--violet); background: #f3f1ff; box-shadow: inset 0 0 0 1px var(--violet); }
.plan input { width: 18px; height: 18px; margin: 0; accent-color: var(--violet); }
.plan-copy { display: grid; flex: 1; }
.plan-copy strong { font-size: 16px; }
.plan-copy small { color: var(--muted); font-size: 14px; }
.price { font-weight: 800; white-space: nowrap; }
.price span { color: var(--muted); font-size: 13px; font-weight: 500; }
.summary { margin: 0; padding: 4px 16px; border: 1.5px solid var(--line); border-radius: 11px; }
.summary div { display: flex; justify-content: space-between; gap: 16px; padding: 13px 0; border-bottom: 1px solid var(--line); }
.summary div:last-child { border: 0; }
.summary dt { color: var(--muted); }
.summary dd { max-width: 65%; margin: 0; overflow-wrap: anywhere; text-align: right; font-weight: 700; }
.success { padding: 14px; border-radius: 10px; background: #e4f8ed; color: #205d40; font-weight: 700; }
.actions { display: flex; gap: 11px; margin-top: 24px; }
.button { min-height: 50px; padding: 10px 18px; border: 2px solid var(--ink); border-radius: 9px; font: inherit; font-weight: 750; cursor: pointer; transition: background .15s, transform .1s, box-shadow .15s; }
.button:active:not(:disabled) { transform: translateY(2px); box-shadow: none; }
.button.primary { flex: 1; background: var(--violet); color: white; box-shadow: 0 3px 0 var(--ink); }
.button.primary:hover:not(:disabled) { background: var(--violet-dark); }
.button.primary:disabled { border-color: #c8c6d2; background: #dedce7; color: #88899a; box-shadow: none; cursor: not-allowed; }
.button.secondary { background: transparent; }
.button.secondary:hover { background: #f0eef8; }
.footnote { margin: 23px 0 0; color: var(--muted); text-align: center; font-size: 13px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 420px) { .card { padding: 27px 22px 22px; box-shadow: 5px 5px 0 var(--ink); } }

const form = document.querySelector('#signup-form');
const steps = [...document.querySelectorAll('.step')];
const nextButton = document.querySelector('#next');
const backButton = document.querySelector('#back');
const confirmButton = document.querySelector('#confirm');
const progress = document.querySelector('.progress-track');
const progressFill = document.querySelector('#progress-fill');
const stepLabel = document.querySelector('#step-label');
const stepName = document.querySelector('#step-name');
const stepNames = ['Your details', 'Choose a plan', 'Review'];
let currentStep = 0;

function isStepValid() {
  if (currentStep === 0) {
    const name = form.elements.name.value.trim();
    const email = form.elements.email;
    return name.length > 0 && email.value.trim() !== '' && email.validity.valid;
  }
  if (currentStep === 1) return Boolean(form.querySelector('input[name="plan"]:checked'));
  return true;
}

function update() {
  steps.forEach((step, index) => { step.hidden = index !== currentStep; });
  stepLabel.textContent = `Step ${currentStep + 1} of 3`;
  stepName.textContent = stepNames[currentStep];
  progress.setAttribute('aria-valuenow', String(currentStep + 1));
  progressFill.style.width = `${((currentStep + 1) / 3) * 100}%`;
  backButton.hidden = currentStep === 0;
  nextButton.hidden = currentStep === 2;
  confirmButton.hidden = currentStep !== 2;
  nextButton.disabled = !isStepValid();
  if (currentStep === 2) {
    const name = form.elements.name.value.trim();
    document.querySelector('#summary-name').textContent = name.split(/\s+/)[0] || 'friend';
    document.querySelector('#summary-name-value').textContent = name;
    document.querySelector('#summary-email').textContent = form.elements.email.value.trim();
    document.querySelector('#summary-plan').textContent = form.querySelector('input[name="plan"]:checked').value;
  }
}

form.addEventListener('input', update);
form.addEventListener('change', update);
nextButton.addEventListener('click', () => {
  if (isStepValid() && currentStep < 2) { currentStep += 1; update(); }
});
backButton.addEventListener('click', () => {
  if (currentStep > 0) { currentStep -= 1; update(); }
});
form.addEventListener('submit', event => {
  event.preventDefault();
  if (currentStep === 2) {
    document.querySelector('#success').hidden = false;
    confirmButton.disabled = true;
    confirmButton.textContent = 'Confirmed ✓';
  }
});
update();
